$('close-dialog').onclick=closeDialog;$('cancel-dialog').onclick=closeDialog;$('dialog').addEventListener('close',()=>$('submit-form').classList.remove('hidden'));$('new-project').onclick=newProject;document.querySelectorAll('[data-nav]').forEach(n=>n.onclick=()=>{S.view=n.dataset.nav;if(S.view!=='reports')sessionStorage.removeItem('rabbit-hole:research-review');render();});
(async()=>{try{S.token=(await api('/session')).csrf_token;await load();const review=sessionStorage.getItem('rabbit-hole:research-review');const active=sessionStorage.getItem('rabbit-hole:active-project');if(review&&S.projects.some(project=>project.id===review)){await showResearchReview(review);}else if(active&&S.projects.some(project=>project.id===active)){await openProject(active);if(S.project?.focus_product_id){const step=S.project.guidance?.step||'identification';openProduct(S.project.focus_product_id,step);}}else render();}catch(e){warn(e.message);$('content').replaceChildren(empty('业务工作台尚未就绪','请确认服务已启动并完成数据库迁移。现有历史数据不会被删除。'));}})();setInterval(refresh,5000);
